"""Matrix chain multiplication via interval DP, verified by independent recomputation.

Given a chain of matrices A_0 ... A_{n-1} where A_i has shape
(dims[i], dims[i+1]), compute the parenthesization minimizing the number
of scalar multiplications.

The DP result is never trusted: `best_order` also returns the parsed
tree so `cost_of` can recompute the cost from the structure itself,
and tests compare against exhaustive enumeration of all parenthesizations.
"""

from __future__ import annotations

from dataclasses import dataclass
from itertools import count as _count


# A parenthesization is either a leaf (matrix index) or an internal node.
# We use a small class so trees are unambiguous vs. plain tuples of ints.
@dataclass(frozen=True)
class Node:
    left: "Node | int"
    right: "Node | int"

    def __str__(self) -> str:
        if isinstance(self.left, int):
            ls = f"A{self.left}"
        else:
            ls = str(self.left)
        if isinstance(self.right, int):
            rs = f"A{self.right}"
        else:
            rs = str(self.right)
        return f"({ls} {rs})"


def _flatten(node: Node | int, out: list[int]) -> None:
    """Collect leaf indices in left-to-right order."""
    if isinstance(node, int):
        out.append(node)
    else:
        _flatten(node.left, out)
        _flatten(node.right, out)


def best_order(dims: list[int]) -> tuple[int, str, Node]:
    """Interval DP over chain lengths.

    Returns (min_scalar_mults, parenthesization_string, paren_tree).
    dims has length n+1 for n matrices; n == 0 returns (0, "", None-ish).
    """
    n = len(dims) - 1
    if n < 0:
        raise ValueError("dims must contain at least 2 entries (1 matrix)")
    if any(d <= 0 for d in dims):
        raise ValueError("all dimensions must be positive")
    if n == 0:
        return 0, "", None  # type: ignore[return-value]

    # cost[i][j]: min scalar mults for A_i..A_j
    # split[i][j]: optimal split point k (A_i..A_k)(A_{k+1}..A_j)
    INF = float("inf")
    cost = [[0] * n for _ in range(n)]
    split = [[0] * n for _ in range(n)]

    for length in range(2, n + 1):  # subchain length
        for i in range(n - length + 1):
            j = i + length - 1
            cost[i][j] = INF
            best_k, best_c = -1, INF
            for k in range(i, j):
                c = (
                    cost[i][k]
                    + cost[k + 1][j]
                    + dims[i] * dims[k + 1] * dims[j + 1]
                )
                if c < best_c:
                    best_c, best_k = c, k
            cost[i][j] = best_c
            split[i][j] = best_k

    def build(i: int, j: int) -> Node | int:
        if i == j:
            return i
        return Node(build(i, split[i][j]), build(split[i][j] + 1, j))

    tree = build(0, n - 1)
    assert isinstance(tree, Node)
    return cost[0][n - 1], str(tree), tree


def cost_of(tree: Node | int, dims: list[int]) -> int:
    """Recompute multiplication cost directly from a paren tree.

    Completely independent of the DP: recursively computes each subtree's
    result shape and accumulates dims[p]*dims[mid]*dims[r] at every join.
    Also verifies leaves are exactly A_0..A_{n-1} in order.
    """
    def rec(node: Node | int) -> tuple[int, int, int]:
        # returns (rows, cols, accumulated cost)
        if isinstance(node, int):
            return dims[node], dims[node + 1], 0
        lr, lc, lcost = rec(node.left)
        rr, rc, rcost = rec(node.right)
        if lc != rr:
            raise ValueError(f"incompatible shapes {lr}x{lc} and {rr}x{rc}")
        return lr, rc, lcost + rcost + lr * lc * rc

    rows, cols, total = rec(tree)
    # sanity: overall shape matches multiplying the whole chain in order
    n = len(dims) - 1
    leaves: list[int] = []
    _flatten(tree, leaves)
    expected = list(range(n))
    if rows != dims[0] or cols != dims[n]:
        raise ValueError("result shape does not match full chain")
    if len(leaves) != len(expected) or sorted(leaves) != expected:
        raise ValueError("tree leaves are not exactly A_0..A_{n-1}")
    return total


def all_parenthesizations(n: int):
    """Yield every full binary parenthesization of A_0..A_{n-1}.

    Recursive enumerator: a chain of n matrices splits at each of the
    n-1 possible top-level cut points. Count = Catalan(n-1).
    """
    if n < 0:
        raise ValueError("n must be >= 0")

    def gen(lo: int, hi: int):
        # yields trees for A_lo..A_hi
        if lo == hi:
            yield lo
            return
        for k in range(lo, hi):
            for left in gen(lo, k):
                for right in gen(k + 1, hi):
                    yield Node(left, right)

    if n == 0:
        return iter(())
    return gen(0, n - 1)


def brute_force_best(dims: list[int]) -> tuple[int, Node]:
    """Exhaustively evaluate every parenthesization; return (min_cost, some_argmin)."""
    best_cost: int | None = None
    best_tree: Node | None = None
    for tree in all_parenthesizations(len(dims) - 1):
        c = cost_of(tree, dims)
        if best_cost is None or c < best_cost:
            best_cost, best_tree = c, tree
    assert best_cost is not None and best_tree is not None
    return best_cost, best_tree

